/* ---------- small feedback ---------- */
function hint(msg, secs) { const h = $('hint'); h.innerHTML = tx(msg); h.classList.add('on'); clearTimeout(R.hintT); R.hintT = setTimeout(() => h.classList.remove('on'), (secs || 3.2) * 1000); }
